// 全ての組合せを試し，product(1)〜product(6) が正しくなるものがちょうど1つかを確かめる
const inits = [0, 1];
const updates = { 'p ＋ i': (p, i) => p + i, 'p × i': (p, i) => p * i };
const fact = (n) => (n <= 1 ? 1 : n * fact(n - 1));
const ok = [];
for (const a of inits) {
  for (const [b, f] of Object.entries(updates)) {
    let good = true;
    for (let n = 1; n <= 6; n++) {
      let p = a;
      for (let i = 1; i <= n; i++) p = f(p, i);
      if (p !== fact(n)) good = false;
    }
    if (good) ok.push('a: ' + a + ' ／ b: ' + b);
  }
}
return ok.length === 1 ? ok[0] : 'answers=' + ok.length;
